      const existing = CurioidWorkflowEngine.list();
      const now = new Date().toISOString();
      const flow = { ...checked.flow, updatedAt: now, createdAt: checked.flow.createdAt || now };
      const next = [flow, ...existing.filter(item => item.id !== flow.id)].slice(0, 50);
