  function curioidOsDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open(CURIOID_OS_DB,1);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains('packages'))db.createObjectStore('packages',{keyPath:'id'});if(!db.objectStoreNames.contains('kv'))db.createObjectStore('kv',{keyPath:'key'});};request.onsuccess=()=>{const db=request.result;db.onversionchange=()=>db.close();resolve(db);};request.onerror=()=>reject(request.error||new Error('Could not open local OS storage.'));});}
