  const curioidOsList=()=>curioidOsTx('packages','readonly',store=>new Promise((resolve,reject)=>{const req=store.getAll();req.onsuccess=()=>resolve((req.result||[]).sort((a,b)=>String(a.package?.manifest?.name||'').localeCompare(String(b.package?.manifest?.name||''))));req.onerror=()=>reject(req.error);}));
