    const token=uid()+uid()+Date.now().toString(36),overlay=document.createElement('div');overlay.className='curioid-os-runtime';overlay.innerHTML=`<header><div><small>CURIOID / LOCAL WORLD</small><b>${esc(pkg.manifest.name)}</b><span>${esc(pkg.manifest.version)} · SANDBOXED SESSION</span></div><button type="button" data-os-runtime-close>Close world ×</button></header><iframe title="${esc(pkg.manifest.name)} local operating system" sandbox="allow-scripts allow-downloads"></iframe><div class="user-os-runtime-status" data-os-runtime-status>Starting isolated local world…</div>`;document.body.appendChild(overlay);
