      if(method==='capabilities.call'){const capId=String(payload?.id||''),cap=CurioidKernel.getCapability(capId);if(!cap||!['public','granted'].includes(cap.access))throw new Error('This capability is not available to local OSs.');if(!window.confirm(`Allow ${pkg.manifest.name} to call “${cap.name}” from ${cap.ownerExperienceId}?${cap.access==='granted'?' The owner must also have granted this OS access.':''}`))throw new Error('Capability call cancelled.');return CurioidKernel.requestCapability(capId,payload?.input||{},{fromExperienceId:runtimeId});}
      if(method==='permissions.list'){const owned=CurioidKernel.getCapabilities({ownerExperienceId:runtimeId}).filter(cap=>cap.access==='granted');return Promise.all(owned.map(async cap=>({capabilityId:cap.id,name:cap.name,grants:await CurioidKernel.getCapabilityGrants(cap.id)})));}
      if(method==='permissions.grant'||method==='permissions.revoke'){const capId=String(payload?.capabilityId||''),requesterId=String(payload?.requesterExperienceId||''),cap=CurioidKernel.getCapability(capId);if(!cap||cap.ownerExperienceId!==runtimeId||cap.access!=='granted')throw new Error('This OS can only manage grants for its own granted capabilities.');const requester=CurioidKernel.getExperience(requesterId);if(!requester)throw new Error('The requested experience is not currently registered. Open it first, then manage its access.');const grant=method==='permissions.grant';if(!window.confirm(`${grant?'Grant':'Revoke'} “${cap.name}” access for ${requester.name} (${requesterId})?`))throw new Error('Permission change cancelled.');return grant?CurioidKernel.grantCapability(capId,requesterId):CurioidKernel.revokeCapability(capId,requesterId);}
      if(method==='host.notify'){overlay.querySelector('[data-os-runtime-status]').textContent=String(payload?.message||'').slice(0,240);return true;}
