      for(const cap of pkg.manifest.capabilities){const capId=`useros.${id}.${cap.id}`;const record=CurioidKernel.registerCapability({id:capId,ownerExperienceId:runtimeId,name:cap.name,description:cap.description,version:pkg.manifest.version,access:cap.access==='public'?'public':'granted',inputSchema:{format:'JSON'},outputSchema:{format:'JSON'},handler:input=>invoke('capability',{id:cap.id,input})});runtime.unregister.push(()=>CurioidKernel.unregisterCapability(record.id,runtimeId));}
