      const old=q('[data-cos-permissions-dialog]');if(old)old.remove();
      const dialog=document.createElement('dialog');dialog.className='cos-permissions-dialog';dialog.dataset.cosPermissionsDialog='true';dialog.addEventListener('close',()=>dialog.remove(),{once:true});
      if(!caps.length){dialog.innerHTML=`<section><h3>Capability access</h3><p>This OS has no active granted capabilities. Add a capability and set its access to <code>granted</code> in the builder.</p><button type="button" data-cos-permissions-close>Done</button></section>`;root.appendChild(dialog);dialog.showModal();return;}
