      const snapshots=await Promise.all(caps.map(async cap=>({cap,grants:await CurioidKernel.getCapabilityGrants(cap.id)})));
      const granted=new Set(snapshots.flatMap(item=>item.grants.map(grant=>`${grant.capabilityId}::${grant.requesterExperienceId}`)));
      dialog.innerHTML=`<section><header><div><small>CURIOID / LOCAL PERMISSIONS</small><h3>Manage access · ${esc(id)}</h3><p>Choose which currently registered experiences may call each capability. Public capabilities do not appear here because they are available to everyone.</p></div><button type="button" data-cos-permissions-close aria-label="Close">×</button></header>${snapshots.map(({cap})=>`<article><h4>${esc(cap.name)}</h4><p>${esc(cap.description||cap.id)} <code>${esc(cap.id)}</code></p><div>${experiences.length?experiences.map(exp=>{const key=`${cap.id}::${exp.id}`,checked=granted.has(key);return`<label><input type="checkbox" data-cos-permission-toggle data-capability="${esc(cap.id)}" data-requester="${esc(exp.id)}" ${checked?'checked':''}><span><b>${esc(exp.name||exp.id)}</b><small>${esc(exp.id)}</small></span></label>`;}).join(''):'<p>No other experiences are registered yet. Open the world that should receive access, then return here.'}</div></article>`).join('')}<footer>Changes take effect immediately. Revoke access at any time. Every requester still needs to be registered in this browser session.</footer><button type="button" data-cos-permissions-close>Done</button></section>`;
