    root.addEventListener('change',async event=>{if(event.target.matches('[data-cos-advanced]')){if(!setAdvancedMode(event.target.checked))return;setStatus(event.target.checked?'Advanced mode unlocked. All creator controls are now available.':'Simple mode restored. Your next save uses the visual builder.');return;}if(event.target.matches('[data-cos-template]')){const preset=CURIOID_OS_SIMPLE_PRESETS[event.target.value]||CURIOID_OS_SIMPLE_PRESETS.personal;qa('[data-cos-tool]').forEach(input=>input.checked=preset.includes(input.dataset.cosTool));return;}if(event.target.matches('[data-cos-permission-toggle]')){const check=event.target,capabilityId=check.dataset.capability,requesterId=check.dataset.requester,grant=check.checked;try{await (grant?CurioidKernel.grantCapability(capabilityId,requesterId):CurioidKernel.revokeCapability(capabilityId,requesterId));}catch(error){check.checked=!grant;alert(`Permission change failed: ${error.message}`);}return;}if(event.target.matches('[data-cos-import]')){const file=event.target.files?.[0];try{if(!file) return;if(file.size>CURIOID_OS_MAX_PACKAGE)throw new Error('The .curioidos package exceeds 8 MB.');const pkg=curioidOsValidatePackage(JSON.parse(await file.text()));populate(pkg);currentPackage=pkg;const existing=await curioidOsGet(pkg.manifest.id);if(existing&&!window.confirm('Replace the existing local package?'))return;await curioidOsPut({id:pkg.manifest.id,package:pkg,enabled:true,createdAt:existing?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()});setStatus(`Imported “${pkg.manifest.name}” locally. You may edit or launch it.`);refreshWorlds();}catch(error){setStatus(`Import rejected: ${error.message}`);}finally{event.target.value='';}}
      if(event.target.matches('[data-cos-review-import]')){loadReview(event.target.files?.[0]);event.target.value='';}
      if(event.target.matches('[data-cos-backup-import]')){try{await restoreBackup(event.target.files?.[0]);}catch(error){setStatus(`Backup restore rejected: ${error.message}`);}finally{event.target.value='';}}
      if(event.target.matches('[data-cos-assets]')){const files=[...(event.target.files||[])],originalAssets=[...localAssets];try{for(const file of files){if(localAssets.length>=24)throw new Error('This OS already has the maximum of 24 assets.');if(file.size>2*1024*1024)throw new Error(`${file.name} exceeds the 2 MB per-file limit.`);const mime=String(file.type||'').toLowerCase();if(!CURIOID_OS_ASSET_TYPES.test(mime))throw new Error(`${file.name} has an unsupported type (${mime||'unknown'}).`);const name=String(file.name||'asset').replace(/\\/g,'/').split('/').pop().replace(/[^a-z0-9._ -]/gi,'_').slice(0,100);if(localAssets.some(item=>item.name.toLowerCase()===name.toLowerCase()))throw new Error(`An asset named ${name} already exists.`);const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error(`Could not read ${name}.`));reader.readAsDataURL(file);});localAssets.push({name,mime,size:file.size,dataUrl});}const total=localAssets.reduce((sum,item)=>sum+(item.size||0),0);if(total>CURIOID_OS_MAX_ASSET_BYTES)throw new Error('The combined asset library exceeds 4 MB.');renderAssets();setStatus(`${files.length} asset file${files.length===1?'':'s'} added locally. Save or export to include them in your package.`);}catch(error){localAssets.splice(0,localAssets.length,...originalAssets);setStatus(error.message);renderAssets();}finally{event.target.value='';}}
    });
