  // One native fullscreen controller shared by every desktop-style OS.
  // The browser remains in charge of the fullscreen state (including Escape).
  function bindOsFullscreen(shell, button, onError = () => {}) {
    let alive = true;
    const sync = () => {
      if (!button) return;
      const active = document.fullscreenElement === shell;
      button.setAttribute('aria-pressed', String(active));
      button.setAttribute('aria-label', active ? 'Exit fullscreen' : 'Enter fullscreen');
      button.title = active ? 'Exit fullscreen' : 'Enter fullscreen';
    };
    const toggle = async () => {
      if (!alive) return;
      try {
        if (!shell || typeof shell.requestFullscreen !== 'function') throw new Error('Fullscreen is not supported by this browser.');
        if (document.fullscreenElement === shell) {
          if (document.exitFullscreen) await document.exitFullscreen();
          else throw new Error('The browser cannot exit fullscreen from this page.');
        } else {
          if (document.fullscreenElement) {
            if (!document.exitFullscreen) throw new Error('The browser cannot switch fullscreen elements.');
            await document.exitFullscreen();
          }
          await shell.requestFullscreen();
        }
      } catch (error) {
        try { onError(error?.message || 'Fullscreen is unavailable in this browser.'); } catch (_) {}
      } finally { sync(); }
    };
    button?.addEventListener('click', toggle);
    document.addEventListener('fullscreenchange', sync);
    sync();
    return {
      toggle,
      sync,
      destroy() {
        if (!alive) return;
        alive = false;
        button?.removeEventListener('click', toggle);
        document.removeEventListener('fullscreenchange', sync);
        if (document.fullscreenElement === shell && document.exitFullscreen) { try { Promise.resolve(document.exitFullscreen()).catch(() => {}); } catch (_) {} }
      }
    };
  }

  // CURIOID Workshop: small, local-first services shared by independent experiences.
  // Each service works on explicitly supplied input or a selected Kernel artifact.
  const CURIOID_WORKSHOP_ID = 'curioid-workshop';

  function workshopParseDelimited(source, delimiter) {
    const text = String(source ?? '');
    const rows = [];
    let row = [], field = '', quoted = false;
    for (let i = 0; i < text.length; i++) {
      const char = text[i];
      if (quoted) {
        if (char === '"' && text[i + 1] === '"') { field += '"'; i++; }
        else if (char === '"') quoted = false;
        else field += char;
      } else if (char === '"' && field.length === 0) quoted = true;
      else if (char === delimiter) { row.push(field); field = ''; }
      else if (char === '\n' || char === '\r') {
        if (char === '\r' && text[i + 1] === '\n') i++;
        row.push(field); field = '';
        if (row.some(value => value !== '')) rows.push(row);
        row = [];
      } else field += char;
    }
    row.push(field);
    if (row.some(value => value !== '')) rows.push(row);
    if (quoted) throw new Error('The delimited text contains an unfinished quoted field.');
    return rows;
  }

  function workshopDelimitedCell(value, delimiter) {
    const text = value === null || value === undefined ? '' : typeof value === 'object' ? JSON.stringify(value) : String(value);
    return text.includes('"') || text.includes('\n') || text.includes('\r') || text.includes(delimiter)
      ? `"${text.replace(/"/g, '""')}"` : text;
  }

  function workshopRowsToDelimited(rows, delimiter) {
    return rows.map(row => row.map(value => workshopDelimitedCell(value, delimiter)).join(delimiter)).join('\r\n');
  }

  function workshopConvertFormat(input) {
    const mode = String(input?.mode || 'json-pretty');
    const source = String(input?.text ?? '');
    if (new TextEncoder().encode(source).byteLength > 1024 * 1024) throw new Error('The Format Bench accepts up to 1 MB of input at a time.');
    let output = '';
    let mediaType = 'text/plain';
    if (mode === 'json-pretty' || mode === 'json-minify') {
      const value = JSON.parse(source);
      output = JSON.stringify(value, null, mode === 'json-pretty' ? 2 : 0);
      mediaType = 'application/json';
    } else if (mode === 'json-to-csv') {
      const value = JSON.parse(source);
      if (!Array.isArray(value) || !value.length || value.some(row => !row || typeof row !== 'object' || Array.isArray(row))) {
        throw new Error('JSON to CSV expects a non-empty array of objects.');
      }
      const headers = [...new Set(value.flatMap(row => Object.keys(row)))];
      if (!headers.length) throw new Error('The JSON objects do not contain any fields.');
      output = workshopRowsToDelimited([headers, ...value.map(row => headers.map(header => row[header] ?? ''))], ',');
      mediaType = 'text/csv';
    } else if (mode === 'csv-to-json' || mode === 'tsv-to-json') {
      const rows = workshopParseDelimited(source, mode === 'csv-to-json' ? ',' : '\t');
      if (rows.length < 2) throw new Error('The table needs a header row and at least one data row.');
      const headers = rows[0].map((header, index) => String(header || `Column ${index + 1}`).trim());
      const objects = rows.slice(1).map(row => Object.fromEntries(headers.map((header, index) => [header, row[index] ?? ''])));
      output = JSON.stringify(objects, null, 2);
      mediaType = 'application/json';
    } else if (mode === 'csv-to-tsv' || mode === 'tsv-to-csv') {
      const from = mode === 'csv-to-tsv' ? ',' : '\t';
      const to = mode === 'csv-to-tsv' ? '\t' : ',';
      output = workshopRowsToDelimited(workshopParseDelimited(source, from), to);
      mediaType = mode === 'csv-to-tsv' ? 'text/tab-separated-values' : 'text/csv';
    } else throw new Error('Choose a supported format operation.');
    const outputBytes = new TextEncoder().encode(output).byteLength;
    const result = { output, mediaType, mode, inputBytes: new TextEncoder().encode(source).byteLength, outputBytes };
    if (new TextEncoder().encode(JSON.stringify(result)).byteLength > 3.5 * 1024 * 1024) throw new Error('The converted result is too large to return through a Kernel capability. Save a smaller selection.');
    return result;
  }

  async function workshopInspectArtifact(input) {
    const artifactId = String(input?.artifactId || '').trim();
    if (!artifactId) throw new Error('Choose an artifact to inspect.');
    const artifact = await CurioidKernel.getArtifact(artifactId);
    if (!artifact) throw new Error('That artifact could not be found in local Kernel storage.');
    const content = artifact.content || {};
    let preview = '';
    if (content.kind === 'text') preview = String(content.text || '').slice(0, 2400);
    else if (content.kind === 'json') {
      try { preview = JSON.stringify(content.value, null, 2).slice(0, 2400); } catch (_) { preview = '[JSON preview unavailable]'; }
    }
    return {
      id: artifact.id, title: artifact.title, type: artifact.type,
      createdAt: artifact.createdAt, updatedAt: artifact.updatedAt,
      sourceExperienceId: artifact.sourceExperienceId,
      recipientExperienceId: artifact.recipientExperienceId,
      contentKind: content.kind || 'unknown', mediaType: content.mediaType || artifact.type || 'unknown',
      size: Number(content.size) || 0, metadata: artifact.metadata || {},
      provenance: Array.isArray(artifact.provenance) ? artifact.provenance : [], preview
    };
  }

  async function workshopCreateThumbnail(input) {
    const artifactId = String(input?.artifactId || '').trim();
    const source = await CurioidKernel.getArtifact(artifactId);
    if (!source || source.content?.kind !== 'blob' || !(source.content.blob instanceof Blob)) throw new Error('Choose an image file stored as a Kernel artifact first.');
    if (!String(source.content.mediaType || source.type).startsWith('image/')) throw new Error('The selected artifact is not an image.');
    if (typeof createImageBitmap !== 'function') throw new Error('This browser does not support local image decoding for thumbnails.');
    const bitmap = await createImageBitmap(source.content.blob);
    try {
      const maxDimension = Math.max(64, Math.min(1600, Number(input?.maxDimension) || 640));
      const scale = Math.min(1, maxDimension / Math.max(bitmap.width, bitmap.height));
      const width = Math.max(1, Math.round(bitmap.width * scale));
      const height = Math.max(1, Math.round(bitmap.height * scale));
      let canvas, context;
      if (typeof OffscreenCanvas === 'function') {
        canvas = new OffscreenCanvas(width, height);
        context = canvas.getContext('2d');
      } else {
        canvas = document.createElement('canvas'); canvas.width = width; canvas.height = height;
        context = canvas.getContext('2d');
      }
      if (!context) throw new Error('The browser could not create a local thumbnail canvas.');
      context.drawImage(bitmap, 0, 0, width, height);
      let blob;
      if (typeof canvas.convertToBlob === 'function') blob = await canvas.convertToBlob({ type: 'image/webp', quality: .84 });
      else blob = await new Promise((resolve, reject) => canvas.toBlob(result => result ? resolve(result) : reject(new Error('The browser could not encode the thumbnail.')), 'image/webp', .84));
      if (!blob || !blob.size) throw new Error('The browser returned an empty thumbnail.');
      const created = await CurioidKernel.createArtifact({
        sourceExperienceId: CURIOID_WORKSHOP_ID, type: blob.type || 'image/png',
        title: `${source.title || 'Image'} thumbnail`, data: blob,
        metadata: { operation: 'image-thumbnail', derivedFromArtifactId: source.id, width, height, sourceWidth: bitmap.width, sourceHeight: bitmap.height }
      });
      return { artifactId: created.id, title: created.title, width, height, size: blob.size, mediaType: blob.type || 'image/png', derivedFromArtifactId: source.id };
    } finally { try { bitmap.close(); } catch (_) {} }
  }

  function registerCurioidWorkshop() {
    CurioidKernel.registerExperience({ id: CURIOID_WORKSHOP_ID, name: 'CURIOID Workshop', category: 'Shared Services', description: 'Optional local services for inspecting artifacts, converting common formats and creating image thumbnails.' });
    const definitions = [
      { id: 'workshop.inspect-artifact', name: 'Artifact Inspector', description: 'Return metadata, provenance and a small text preview for an explicitly supplied artifact ID.', handler: workshopInspectArtifact, inputSchema: { artifactId: 'string' }, outputSchema: { metadata: 'object', preview: 'string' } },
      { id: 'workshop.convert-format', name: 'Format Bench', description: 'Convert JSON, CSV and TSV using built-in browser JavaScript, without remote services.', handler: workshopConvertFormat, inputSchema: { mode: 'json-pretty | json-minify | json-to-csv | csv-to-json | tsv-to-json | csv-to-tsv | tsv-to-csv', text: 'string' }, outputSchema: { output: 'string', mediaType: 'string', outputBytes: 'number' } },
      { id: 'workshop.image-thumbnail', name: 'Thumbnail Forge', description: 'Create a smaller local WebP or PNG artifact from a selected image artifact.', handler: workshopCreateThumbnail, inputSchema: { artifactId: 'string', maxDimension: 'number, optional' }, outputSchema: { artifactId: 'string', width: 'number', height: 'number' } }
    ];
    for (const definition of definitions) {
      try { CurioidKernel.registerCapability({ ...definition, ownerExperienceId: CURIOID_WORKSHOP_ID, version: '1.0.0', access: 'public' }); }
      catch (error) { console.warn('CURIOID Workshop service could not register:', definition.id, error); }
    }
  }

  window.CurioidWorkshop = Object.freeze({
    id: CURIOID_WORKSHOP_ID, version: '1.0.0',
    services: Object.freeze([
      Object.freeze({ id: 'workshop.inspect-artifact', name: 'Artifact Inspector', kind: 'metadata' }),
      Object.freeze({ id: 'workshop.convert-format', name: 'Format Bench', kind: 'conversion' }),
      Object.freeze({ id: 'workshop.image-thumbnail', name: 'Thumbnail Forge', kind: 'image' })
    ]),
    run(serviceId, input = {}, fromExperienceId = CURIOID_WORKSHOP_ID) {
      return CurioidKernel.requestCapability(serviceId, input, { fromExperienceId });
    },
    convert(text, mode = 'json-pretty', fromExperienceId = CURIOID_WORKSHOP_ID) {
      return CurioidKernel.requestCapability('workshop.convert-format', { text, mode }, { fromExperienceId });
    }
  });

  // A consistent help + backup centre for the desktop operating systems.
  // Backups stay local and include CURIOID localStorage, OS databases and
  // shared Exchange and Kernel databases. External folder permissions are excluded.
  const OS_PROJECT_IDS = new Set(['dead-interface','food-alchemy','echonoise-os','umbra-os','aether-os','aura-synthesis']);
  const OS_BACKUP_DATABASES = new Set(['Doors98_C_Memory','curioid-umbra-studio-v1','aether-os-local-v1','curioid-exchange-v1','curioid-kernel-v1']);
