  // 04 - Echo Cabinet: a step sequencer with expressive synthesis controls.
  const echoToneFamilies=[['glass','Glass room'],['wood','Warm machine'],['wire','Thin wire'],['hollow','Hollow bell'],['brass','Bent brass'],['tape','Worn tape'],['radio','Shortwave radio'],['choir','Ghost choir'],['ice','Ice resonator'],['rust','Rusted gears'],['circuit','Broken circuit'],['reed','Double reed'],['water','Underwater metal'],['steam','Pressure steam'],['rubber','Rubber strings'],['crystal','Crystal oscillator'],['plucked','Plucked wire'],['bowed','Bowed metal'],['marimba','Dark marimba'],['organ','Basement organ'],['sonar','Deep sonar'],['vinyl','Warped vinyl'],['laser','Laser glass'],['engine','Tiny engine'],['wind','Wind through pipes'],['ceramic','Ceramic bowls'],['granular','Granular cloud'],['magnetic','Magnetic tape loop']];
