      ctx.fillStyle='#101018';ctx.fillRect(0,0,w,h);const halo=ctx.createRadialGradient(cx,cy,5,cx,cy,R*3.6);halo.addColorStop(0,colors[3]);halo.addColorStop(1,'#101018');ctx.globalAlpha=.42;ctx.fillStyle=halo;ctx.fillRect(0,0,w,h);ctx.globalAlpha=1;
