    const controls=['echo-count','echo-strength','offset','separation','afterimage-tears','afterimage-scan','image-grain'];controls.forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',redraw));$('[data-select="image-mode"]',root).addEventListener('change',redraw);
    $('[data-action="afterimage-random"]',root).addEventListener('click',()=>{seed=Math.floor(Math.random()*1e7);grainTexture=null;$('[data-select="image-mode"]',root).value=pick(['misregister','heat','negative','xerox','spectral','liquid','signal','ghost']);const vals={'echo-count':[24,40],'echo-strength':[210,300],'offset':[240,520],'separation':[180,300],'afterimage-tears':[60,100],'afterimage-scan':[35,95],'image-grain':[60,100]};Object.entries(vals).forEach(([k,v])=>$(`[data-range="${k}"]`,root).value=String(Math.floor(rand(v[0],v[1]))));redraw();});
