      shards.forEach(s=>{if(!s.got&&Math.hypot((s.x-player.x)*w,(s.y-player.y)*h)<18){s.got=true;score++;combo=Math.min(9,combo+1);comboClock=4.2;boost=Math.min(100,boost+11);burst(s.x,s.y,'#d6ff69',22);}});
      pickups.forEach(o=>{if(!o.taken&&Math.hypot((o.x-player.x)*w,(o.y-player.y)*h)<20){o.taken=true;if(o.type==='shield'){hull=Math.min(100,hull+23);invincible=Math.max(invincible,1.8);burst(o.x,o.y,'#75e6d8',24);}else{boost=Math.min(100,boost+48);burst(o.x,o.y,'#ffb86b',20);}}});
      drones.forEach(d=>{const dx=player.x-d.x,dy=player.y-d.y,dist=Math.hypot(dx,dy)+.001;d.vx=(d.vx+dx/dist*.0008)*.995;d.vy=(d.vy+dy/dist*.0008)*.995;d.x=clamp(d.x+d.vx,.03,.97);d.y=clamp(d.y+d.vy,.04,.96);if(invincible<=0&&Math.hypot((d.x-player.x)*w,(d.y-player.y)*h)<22){hull-=dt*78;player.vx-=dx*.82;player.vy-=dy*.82;}});
