    function saveBlobToDrive(name,blob,room='records',kind='binary'){const filename=String(name||'UNTITLED.BIN').trim().replace(/[\\/:*?"<>|]/g,'-').slice(0,100)||'UNTITLED.BIN';const id='key-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);const file={id,name:filename,room,folder:room,type:kind==='text'?'text':kind,kind,mime:blob.type||'application/octet-stream',size:blob.size,content:'',updated:new Date().toISOString(),userCreated:true};driveBlobs.set(id,blob);virtualFiles.unshift(file);saveVirtualFiles();if(!driveDb)driveError='IndexedDB is unavailable. Binary keys work for this session but cannot survive closing the tab; export a copy before leaving.';return file;}
    const sessionDriveHandles=new Map();
