    function stopTimer(clearTask=true){if(timer){clearInterval(timer);timer=null;}if(clearTask)timerTask=null;}function pauseTimer(){if(timer){clearInterval(timer);timer=null;}}function resumeTimer(){if(!timer&&timerTask)timer=setInterval(timerTask.fn,timerTask.ms);}function startTimer(fn,ms=100){stopTimer();timerTask={fn,ms};timer=setInterval(fn,ms);}
