      $$('[data-retro-menu]',shell).forEach(button=>button.addEventListener('click',()=>{const name=button.dataset.retroMenu;if(!popup.hidden&&popup.dataset.menu===name){popup.hidden=true;return;}popup.dataset.menu=name;popup.innerHTML=menuChoices[name].map(([label,action])=>`<button type="button" data-window-command="${action}">${esc(label)}</button>`).join('');popup.hidden=false;}));
      popup.addEventListener('click',async e=>{const command=e.target.closest('[data-window-command]')?.dataset.windowCommand;if(!command)return;popup.hidden=true;const field=$('textarea,input:not([type=file]),[contenteditable="true"]',entry.content);if(command==='close')closeAppWindow(app);else if(command==='minimize')minimizeAppWindow(app);else if(command==='maximize')toggleAppMaximize(app);else if(command==='front')focusWindow(app);else if(command==='file-manager')open('file-manager');else if(command==='document-editor')open('document-editor');else if(command==='print-queue')open('print-queue');else if(command==='help')open('help');else if(command==='about')toast(null,`${appNames[app]} · Doors98 by Minitender`);else if(command==='refresh'&&entry.refreshTaskList)entry.refreshTaskList();else if(command==='system-monitor')open('system-monitor');else if(command==='select-all'&&field){field.focus();field.select?.();}else if(command==='copy'||command==='cut'){if(field?.value!==undefined){const selected=field.value.slice(field.selectionStart||0,field.selectionEnd||field.value.length);try{await navigator.clipboard?.writeText(selected);}catch(_){}if(command==='cut'&&field.setRangeText)field.setRangeText('',field.selectionStart,field.selectionEnd,'start');}}else if(command==='paste'&&field?.setRangeText){try{const clip=await navigator.clipboard.readText();field.setRangeText(clip,field.selectionStart,field.selectionEnd,'end');}catch(_){toast(null,'Clipboard access was not granted. Use the browser keyboard shortcut instead.');}}});
