        'kanban-board':`<div class="retro-work-app retro-kanban"><form data-kanban-form><label>New task<input name="task" maxlength="180" required placeholder="Add a card to the board…"></label><label>Column<select name="lane"><option value="todo">To do</option><option value="doing">In progress</option><option value="done">Done</option></select></label><button type="submit">Add card</button></form><div class="retro-kanban-columns"><section><h4>TO DO <b data-kanban-count="todo">0</b></h4><div data-kanban-lane="todo"></div></section><section><h4>IN PROGRESS <b data-kanban-count="doing">0</b></h4><div data-kanban-lane="doing"></div></section><section><h4>DONE <b data-kanban-count="done">0</b></h4><div data-kanban-lane="done"></div></section></div><div class="retro-work-toolbar"><button type="button" data-kanban-export>Export board</button><button type="button" data-kanban-clear>Clear completed</button><small data-kanban-status>Saved locally as a C: board key.</small></div></div>`,
        'daily-planner':`<div class="retro-work-app retro-daily-planner"><form data-planner-form><div class="retro-form-grid"><label>Date<input name="date" type="date" required></label><label>Time<input name="time" type="time" value="09:00"></label><label>Task<input name="task" maxlength="180" required placeholder="What needs doing?"></label><label>Duration<select name="duration"><option>15 min</option><option>30 min</option><option>45 min</option><option>1 hour</option><option>2 hours</option><option>Half day</option></select></label></div><button type="submit">Add to planner</button></form><div class="retro-work-toolbar"><button type="button" data-planner-today>Today</button><button type="button" data-planner-export>Export agenda</button><span data-planner-count>0 ITEMS</span></div><div data-planner-list class="retro-planner-list"></div></div>`,
