        'expense-splitter':`<div class="retro-work-app retro-expense-split"><form data-split-form><div class="retro-form-grid"><label>Total amount<input name="total" type="number" min="0" step="0.01" value="48" required></label><label>People<input name="people" type="number" min="1" max="100" value="2" required></label><label>Tip (%)<input name="tip" type="number" min="0" max="100" step="0.5" value="0"></label><label>Currency<select name="currency"><option value="EUR">EUR €</option><option value="USD">USD $</option><option value="GBP">GBP £</option></select></label></div><button type="submit">Split fairly</button></form><div class="retro-split-result" data-split-result>Enter an amount to calculate each share.</div><div class="retro-work-toolbar"><button type="button" data-split-copy>Copy result</button><button type="button" data-split-save>Save calculation to C:</button></div><small>Calculation only. No bank, payment or financial account is connected.</small></div>`,
        'meal-planner':`<div class="retro-work-app retro-meal-planner"><form data-meal-form><div class="retro-form-grid"><label>Day<select name="day"><option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option><option>Saturday</option><option>Sunday</option></select></label><label>Meal<select name="slot"><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snack</option></select></label></div><label>What are we eating?<input name="meal" maxlength="180" required placeholder="A simple meal idea"></label><label>Notes / ingredients<textarea name="notes" rows="2" maxlength="500"></textarea></label><button type="submit">Add meal</button></form><div class="retro-work-toolbar"><button type="button" data-meal-export>Export weekly plan</button><button type="button" data-meal-clear>Clear plan</button><span data-meal-count>0 MEALS</span></div><div data-meal-list class="retro-meal-list"></div></div>`,
        'password-generator':`<div class="retro-work-app retro-password-generator"><div class="retro-form-grid"><label>Length <output data-pgen-length>20</output><input type="range" data-pgen-size min="8" max="64" value="20"></label><label><input type="checkbox" data-pgen-upper checked> Uppercase</label><label><input type="checkbox" data-pgen-lower checked> Lowercase</label><label><input type="checkbox" data-pgen-numbers checked> Numbers</label><label><input type="checkbox" data-pgen-symbols checked> Symbols</label></div><div class="retro-work-toolbar"><button type="button" data-pgen-generate>Generate securely</button><button type="button" data-pgen-copy>Copy</button></div><output class="retro-generated-secret" data-pgen-output>Press Generate. The secret is not saved.</output><small>Uses the browser cryptographic random generator. Nothing is stored in C: automatically. Use a dedicated password manager for important accounts.</small><p data-pgen-status aria-live="polite">READY / LOCAL CRYPTOGRAPHY</p></div>`,
        'colour-palette':`<div class="retro-work-app retro-palette-studio"><div class="retro-work-toolbar"><label>Starting colour <input type="color" data-palette-base value="#55a99f"></label><button type="button" data-palette-generate>Generate palette</button><button type="button" data-palette-save>Save CSS variables to C:</button></div><div class="retro-palette-swatches" data-palette-swatches></div><div class="retro-work-toolbar"><button type="button" data-palette-copy>Copy palette</button><span data-palette-status>FIVE COLOURS / ONE FAMILY</span></div></div>`,
        'pixel-studio':`<div class="retro-work-app retro-pixel-studio"><div class="retro-work-toolbar"><label>Pen <input type="color" data-pixel-colour value="#4b8f83"></label><button type="button" data-pixel-clear>Clear</button><button type="button" data-pixel-save>Save PNG to C:</button><button type="button" data-pixel-export>Download PNG</button><span data-pixel-status>16 × 16 PIXEL CANVAS</span></div><canvas data-pixel-canvas width="256" height="256" aria-label="16 by 16 pixel art canvas"></canvas><small>Click or drag to paint. Every cell is stored as a clean pixel. Your canvas remains local.</small></div>`,
        'svg-workshop':`<div class="retro-work-app retro-svg-workshop"><div class="retro-work-toolbar"><button type="button" data-svg-preview>Preview safely</button><button type="button" data-svg-save>Save SVG to C:</button><button type="button" data-svg-export>Download SVG</button><span data-svg-status>VECTOR WORKSHOP</span></div><textarea data-svg-source rows="12" spellcheck="false" aria-label="SVG source"><svg xmlns="http://www.w3.org/2000/svg" width="480" height="280" viewBox="0 0 480 280"><rect width="480" height="280" rx="18" fill="#e6eee5"/><circle cx="240" cy="128" r="72" fill="#d6b56d"/><path d="M205 142q35 30 70 0" fill="none" stroke="#526f61" stroke-width="8" stroke-linecap="round"/></svg></textarea><div class="retro-svg-preview"><img data-svg-image alt="Safe SVG preview"></div><small>Preview uses an image document, so embedded scripts do not execute. Keep SVG files below 250 KB.</small></div>`,
        'grade-book':`<div class="retro-work-app retro-gradebook"><form data-grade-form><div class="retro-form-grid"><label>Assessment<input name="name" maxlength="120" required placeholder="Essay / quiz / project"></label><label>Score (%)<input name="score" type="number" min="0" max="100" step="0.1" required></label><label>Weight (%)<input name="weight" type="number" min="0.1" max="100" step="0.1" value="100" required></label></div><button type="submit">Add result</button></form><div class="retro-grade-summary"><small>WEIGHTED AVERAGE</small><strong data-grade-average>-</strong><span data-grade-total>0 ASSESSMENTS</span></div><div data-grade-list class="retro-grade-list"></div><div class="retro-work-toolbar"><button type="button" data-grade-export>Export results</button><button type="button" data-grade-clear>Clear results</button></div><small>Weighted average is calculated from the weights you enter. Confirm your institution's grading rules.</small></div>`,
        'metronome':`<div class="retro-work-app retro-metronome"><div class="retro-metronome-readout"><small>KEEP THE ROOM IN TIME</small><strong data-metro-bpm>100</strong><span>BPM</span><i data-metro-pulse></i></div><div class="retro-work-toolbar"><label>Tempo <input type="range" data-metro-slider min="40" max="220" value="100"><output data-metro-value>100 BPM</output></label><label>Beats <select data-metro-beats><option>2</option><option>3</option><option selected>4</option><option>5</option><option>6</option><option>7</option></select></label><label>Accent <select data-metro-accent><option value="yes">First beat</option><option value="no">Even</option></select></label><button type="button" data-metro-start>Start</button><button type="button" data-metro-stop disabled>Stop</button></div><p data-metro-status>Audio begins after you press Start. Master volume applies.</p></div>`,
