        if(glitch==='smear'||glitch==='mixed'){const copy=new Uint8ClampedArray(d);const stride=Math.max(1,Math.round(1+smear*7));for(let y=0;y<h;y+=stride){const shift=Math.round((Math.random()-.5)*smear*120);for(let x=0;x<w;x++){const sx=clamp(x+shift,0,w-1),a=(y*w+x)*4,b=(y*w+sx)*4;d[a]=copy[b];d[a+1]=copy[b+1];d[a+2]=copy[b+2];}}}
        if(chroma>0){const copy=new Uint8ClampedArray(d),offset=Math.max(1,Math.round(chroma*12));for(let y=0;y<h;y++)for(let x=0;x<w;x++){const k=(y*w+x)*4,rx=clamp(x+offset,0,w-1),bx=clamp(x-offset,0,w-1);d[k]=copy[(y*w+rx)*4];d[k+2]=copy[(y*w+bx)*4+2];}}
        if(glitch==='scan'||glitch==='mixed'){const copy=new Uint8ClampedArray(d);for(let y=0;y<h;y+=2){const shift=Math.round(Math.sin(y*.12)*smear*28);for(let x=0;x<w;x++){const sx=clamp(x+shift,0,w-1),a=(y*w+x)*4,b=(y*w+sx)*4;d[a]=copy[b];d[a+1]=copy[b+1];d[a+2]=copy[b+2];}}}
