  const foodFusionRules = Object.create(null);
  const foodPairKey = (a,b) => [String(a),String(b)].sort().join('::');
  function addFoodRule(a,b,id,name,kind,summary,method,rarity='common') {
    foodFusionRules[foodPairKey(a,b)] = {id,name,kind,summary,method,rarity};
  }
  // A deliberately authored starter graph: useful kitchen transformations and recognizable dishes.
  addFoodRule('flour','water','dough','Dough','component','A simple, workable dough. This is the beginning of breads, pastries and noodles.','Mix flour with water gradually until a shaggy dough forms. Knead briefly until smooth, then rest covered.');
  addFoodRule('dough','heat','flatbread','Flatbread','dish','A simple flatbread cooked on a hot surface.','Divide the dough, roll it thin and cook on a hot dry pan, turning until both sides have browned spots.');
  addFoodRule('dough','yeast','risen-dough','Risen dough','component','A light, airy dough ready for a slower bake.','Work yeast into the dough, cover and leave in a warm place until visibly expanded.');
  addFoodRule('risen-dough','heat','loaf-bread','Fresh loaf','dish','A simple crusty loaf with a soft centre.','Shape the risen dough and bake in a fully preheated oven until deeply golden and hollow-sounding when tapped.');
  addFoodRule('flour','egg','pasta-dough','Fresh pasta dough','component','A rich dough that can become fresh pasta.','Combine flour and egg, knead until smooth, wrap and rest before rolling thinly.');
  addFoodRule('pasta-dough','heat','toasted-pasta-dough','Toasted pasta ribbons','component','A crisp, toasted pasta experiment.','Cut the dough into ribbons and toast gently until dry and lightly coloured.');
  addFoodRule('pasta','water','boiled-pasta','Cooked pasta','component','Pasta softened in simmering water and ready for a sauce.','Cook pasta in plenty of salted boiling water until just tender, then drain.');
  addFoodRule('tomato','garlic','tomato-garlic-sauce','Tomato and garlic sauce','component','A savoury base for pasta, toast and slow-cooked dishes.','Gently cook chopped garlic in olive oil, add tomato and simmer until thick and glossy.');
  addFoodRule('boiled-pasta','tomato-garlic-sauce','tomato-garlic-pasta','Tomato and garlic pasta','dish','A classic quick pasta built from a bright tomato sauce.','Toss the cooked pasta through the sauce with a splash of pasta water. Finish with herbs and black pepper.');
  addFoodRule('rice','water','rinsed-rice','Rinsed rice','component','Clean rice, ready for cooking.','Rinse the rice in cool water until the water is less cloudy, then drain well.');
  addFoodRule('rinsed-rice','heat','steamed-rice','Steamed rice','dish','Fluffy rice with separate grains.','Add the rice and measured water to a covered pot. Simmer gently until tender, then rest off the heat.');
  addFoodRule('tomato','onion','sofrito-base','Tomato and onion base','component','A savoury base for stews, sauces and baked dishes.','Soften chopped onion slowly, add tomato and cook until the mixture is thick and sweet.');
  addFoodRule('sofrito-base','chickpea','chickpea-tomato-stew','Chickpea and tomato stew','dish','A hearty, pantry-friendly stew with a rich tomato base.','Add cooked chickpeas and vegetable stock to the tomato base. Simmer until thick, then finish with herbs and lemon.');
  addFoodRule('chickpea','sesame','sesame-chickpea-mash','Sesame chickpea mash','component','A coarse chickpea and sesame preparation that can be seasoned into a dip.','Mash cooked chickpeas with toasted sesame, olive oil, lemon and a little water. For classic hummus, combine chickpeas with tahini instead.');
  addFoodRule('chickpea','tahini','hummus','Hummus','dish','A smooth chickpea dip enriched with tahini.','Blend cooked chickpeas with tahini, lemon juice, garlic, olive oil and enough cold water to make a creamy texture. Season to taste.');
  addFoodRule('chickpea','garlic','falafel-mix','Falafel mixture','component','A fragrant chickpea mixture ready to shape.','Mash cooked chickpeas with garlic, herbs and cumin. Add a little flour if needed to help the mixture hold together.');
  addFoodRule('falafel-mix','heat','falafel','Falafel patties','dish','Golden chickpea patties with herbs and warm spice.','Shape the mixture into small patties and bake or pan-fry until crisp and hot all the way through.');
  addFoodRule('potato','heat','baked-potato','Baked potato','dish','A fluffy potato with a crisp skin.','Scrub and dry the potato, prick the skin and bake until the centre is completely soft.');
  addFoodRule('potato','oil','crispy-potatoes','Crispy potatoes','dish','Golden potato pieces with crisp edges.','Cut potatoes into even pieces, coat lightly with oil and roast in a hot oven, turning once until crisp and tender.');
  addFoodRule('baked-potato','cheese','cheese-baked-potato','Cheese baked potato','dish','A baked potato finished with melted cheese.','Split the hot baked potato, fluff the centre and add cheese. Return briefly to the oven until melted.');
  addFoodRule('tomato','pepper','shakshuka-base','Shakshuka base','component','A gently spiced tomato and pepper pan sauce.','Soften pepper and onion, add chopped tomato, cumin and paprika, then simmer until thick.');
  addFoodRule('shakshuka-base','egg','shakshuka','Shakshuka','dish','Eggs gently cooked in a spiced tomato and pepper sauce.','Make small wells in the simmering sauce, add eggs, cover and cook until the whites are set.');
  addFoodRule('lentil','water','soaked-lentils','Soaked lentils','component','Lentils softened before cooking.','Rinse the lentils and soak briefly in cool water, then drain.');
  addFoodRule('soaked-lentils','heat','cooked-lentils','Cooked lentils','component','Tender lentils ready for soups, salads and stews.','Simmer the lentils in fresh water or stock until tender, then drain if needed.');
  addFoodRule('cooked-lentils','tomato','lentil-tomato-stew','Lentil and tomato stew','dish','A filling, tomato-rich lentil stew.','Simmer cooked lentils with tomato, onion, cumin and stock. Finish with lemon and chopped herbs.');
  addFoodRule('oats','milk','porridge-base','Creamy porridge','component','A warm, creamy oat base for sweet or savoury toppings.','Simmer oats with milk, stirring until soft and creamy.');
  addFoodRule('porridge-base','apple','apple-oat-porridge','Apple and oat porridge','dish','Warm oats with soft apple and gentle sweetness.','Fold chopped apple and cinnamon into the porridge and cook until the fruit softens.');
  addFoodRule('flour','butter','pastry-dough','Short pastry','component','A crumbly pastry dough for pies and tarts.','Rub cold butter into flour, add just enough cold water to bring it together and chill before rolling.');
  addFoodRule('pastry-dough','apple','apple-tart-filling','Apple tart filling','component','A fragrant apple filling for a simple tart.','Slice the apple thinly and toss with a little sugar and cinnamon.');
  addFoodRule('apple-tart-filling','heat','apple-tart','Apple tart','dish','A crisp pastry tart filled with cinnamon apples.','Arrange the apple filling over rolled pastry and bake until the fruit is tender and the edges are golden.');
  addFoodRule('spinach','cheese','spinach-cheese-filling','Spinach and cheese filling','component','A savoury filling for pies and pastries.','Wilt the spinach, cool and squeeze out excess liquid. Mix with crumbled cheese and herbs.');
  addFoodRule('spinach-cheese-filling','dough','spinach-pie','Spinach and cheese pie','dish','A savoury pie with spinach, cheese and herbs.','Enclose the filling in thin dough or pastry and bake until crisp and cooked through.');
  addFoodRule('egg','potato','potato-egg-mixture','Potato and egg mixture','component','The base of a simple potato omelette.','Cook thinly sliced potato until tender, cool slightly and fold through beaten egg.');
  addFoodRule('potato-egg-mixture','heat','potato-tortilla','Potato tortilla','dish','A thick Spanish-style potato and egg tortilla.','Cook gently in a non-stick pan until nearly set, then turn carefully and cook the other side.');
  addFoodRule('chicken','lemon','lemon-chicken-marinade','Lemon-marinated chicken','component','Chicken coated in lemon and seasoning before cooking.','Coat the chicken with lemon, garlic, oil and herbs. Keep it chilled while it marinates.');
  addFoodRule('lemon-chicken-marinade','heat','lemon-chicken','Lemon herb chicken','dish','Bright lemon and herb chicken.','Cook the chicken thoroughly until steaming hot throughout and no raw areas remain. Rest briefly before serving.');
  addFoodRule('sardine','tomato','sardine-tomato-topping','Sardine and tomato topping','component','A savoury topping for toast or warm bread.','Break the sardines into pieces and mix with chopped tomato, lemon and herbs.');
  addFoodRule('sardine-tomato-topping','bread','sardine-toast','Sardine tomato toast','dish','Crisp toast with sardines, tomato and lemon.','Toast the bread and spoon over the sardine and tomato mixture. Finish with lemon and herbs.');
  addFoodRule('cabbage','vinegar','quick-pickled-cabbage','Quick-pickled cabbage','component','A sharp, crunchy cabbage pickle.','Finely shred the cabbage and toss with vinegar, salt and a little sugar. Rest until lightly softened.');
  addFoodRule('yogurt','cucumber','tzatziki','Tzatziki','dish','A cool cucumber and yogurt dip with garlic and herbs.','Grate and squeeze the cucumber dry. Stir into thick yogurt with garlic, lemon, herbs and a little salt.');
  addFoodRule('tomato','cucumber','tomato-cucumber-salad','Tomato and cucumber salad','component','A crisp base for a fresh Mediterranean salad.','Cut ripe tomatoes and cucumber into generous pieces and season lightly.');
  addFoodRule('tomato-cucumber-salad','cheese','greek-village-salad','Greek village salad','dish','A simple village salad with tomato, cucumber and cheese.','Add olives, cheese, olive oil and oregano to the tomato and cucumber. Toss gently and serve fresh.');
  addFoodRule('banana','oats','banana-oat-batter','Banana oat batter','component','A simple batter for quick breakfast pancakes.','Mash ripe banana and mix with oats, egg and a little milk until spoonable.');
  addFoodRule('banana-oat-batter','heat','banana-oat-pancakes','Banana oat pancakes','dish','Soft banana and oat pancakes.','Cook small rounds on a lightly greased pan over medium heat, turning when the surface begins to set.');
  addFoodRule('pumpkin','coconut','pumpkin-coconut-curry','Pumpkin coconut curry','dish','A gently spiced pumpkin curry with a creamy coconut finish.','Soften onion and curry spices, add pumpkin and coconut milk, then simmer until the pumpkin is tender.');
  addFoodRule('mushroom','rice','mushroom-rice-base','Mushroom rice base','component','A savoury mushroom and rice combination.','Brown sliced mushrooms with onion, stir in rice and add hot stock. Cover and cook until tender.');
  addFoodRule('mushroom-rice-base','cheese','mushroom-rice-bake','Mushroom and cheese rice bake','dish','A comforting baked rice dish with mushrooms and cheese.','Fold cheese through the cooked mushroom rice, transfer to an oven dish and bake until golden at the edges.');
  addFoodRule('carrot','flour','carrot-cake-base','Carrot cake mixture','component','A spiced carrot mixture ready for baking.','Mix grated carrot with flour, egg, sugar, cinnamon and chopped nuts until just combined.');
  addFoodRule('carrot-cake-base','heat','carrot-spice-cake','Carrot spice cake','dish','A warmly spiced cake with grated carrot.','Bake the mixture in a lined tin until risen and a skewer inserted in the centre comes out clean.');
  addFoodRule('eggplant','tomato','eggplant-tomato-base','Eggplant tomato base','component','Soft eggplant layered with a rich tomato sauce.','Brown the eggplant, then simmer with tomato, garlic and herbs until soft.');
  addFoodRule('eggplant-tomato-base','cheese','eggplant-bake','Eggplant and tomato bake','dish','A layered bake of eggplant, tomato and cheese.','Layer the eggplant mixture with cheese and bake until bubbling and tender.');
  addFoodRule('cabbage','carrot','cabbage-slaw-mix','Cabbage slaw mix','component','A crisp shredded vegetable base.','Shred cabbage and carrot finely and toss together.');
  addFoodRule('cabbage-slaw-mix','vinegar','crunchy-cabbage-slaw','Crunchy cabbage slaw','dish','A crisp sweet-sour cabbage side.','Dress the shredded vegetables with vinegar, a little honey and black pepper. Rest briefly before serving.');
  addFoodRule('basil','nuts','basil-nut-pesto','Basil nut pesto','component','A coarse green pesto with nuts and basil.','Crush basil with nuts, garlic and olive oil. Add a little water to loosen if needed.');
  addFoodRule('basil-nut-pesto','pasta','pesto-pasta','Basil pesto pasta','dish','Pasta coated in a fragrant basil and nut pesto.','Toss cooked pasta with pesto and a splash of pasta water until glossy.');
  addFoodRule('chickpea','lemon','lemon-chickpea-salad','Lemon chickpea salad','dish','A bright chickpea salad with lemon and herbs.','Toss cooked chickpeas with lemon, olive oil, herbs, onion and black pepper.');
  addFoodRule('orange','cocoa','orange-cocoa-cake','Orange cocoa cake','dish','A cocoa cake with fragrant orange zest.','Fold orange zest and juice into a cocoa cake batter and bake until risen and set.');

  // Additional authored recipes extend the graph into breakfast, sides, drinks and comfort food.
  addFoodRule('onion','oil','soft-onion','Softened onion','component','A sweet, gently cooked onion base for sauces and savoury dishes.','Cook sliced onion slowly in olive oil over moderate heat until soft and translucent.');
  addFoodRule('soft-onion','tomato','slow-tomato-base','Slow tomato and onion base','component','A richer tomato base for simple sauces and stews.','Add chopped tomato to the softened onion and cook slowly until reduced and glossy.');
  addFoodRule('garlic','oil','garlic-oil','Garlic oil','component','A fragrant oil for toast, vegetables and pasta.','Warm sliced garlic gently in olive oil until aromatic. Do not let it burn.');
  addFoodRule('garlic-oil','bread','garlic-bread','Garlic bread','component','Bread brushed with fragrant garlic oil.','Brush bread with garlic oil and scatter with herbs.');
