      if(phoneVowel&&end-offset>.07&&duration>(end-offset)/sampleRate*.88){
        src.loop=true;src.loopStart=fixedEnd;src.loopEnd=end;
      }
      if(pan){pan.pan.value=enoVoices[voiceId]?.pan||0;gain.connect(pan);pan.connect(a.mix);}else gain.connect(a.mix);
      src.connect(gain);
      const art=clamp(Number(state.vocalArticulation)||72,25,100)/72,peak=.11*velocity*(state.levels[voiceId]??.65)*Math.min(1.12,art);
      const overlapFade=clamp((Number(entry.overlap)||12)/1000,.008,.05),attackAt=Math.max(scheduledAt+.006,Math.min(when+.025,scheduledAt+overlapFade));
      gain.gain.setValueAtTime(.0001,scheduledAt);
      gain.gain.linearRampToValueAtTime(peak,attackAt);
      gain.gain.setTargetAtTime(.0001,when+Math.max(.04,duration-.045),.045);
