      const lexPublishPalette=e.target.closest('[data-eno-lex-publish-palette]');if(lexPublishPalette){handleLexiconAction('publish-palette',lexPublishPalette.closest('[data-eno-window]'));return;}
      const lexSendWord=e.target.closest('[data-eno-lex-send-word]');if(lexSendWord){sendLexiconPhraseToVocal(lexSendWord.dataset.enoLexSendWord);return;}
      const lexVariant=e.target.closest('[data-eno-lex-variant]');if(lexVariant){ensurePronunciationDictionary().then(dict=>runLexiconLookup(lexVariant.closest('[data-eno-window]'),lexVariant.dataset.enoLexVariantWord,dict,Number(lexVariant.dataset.enoLexVariant))).catch(error=>setFeedback(error.message));return;}
      const lexInsert=e.target.closest('[data-eno-lex-insert]');if(lexInsert){const word=lexInsert.dataset.enoLexInsert,phrase=`${state.lyrics.trim()} ${word}`.trim();sendLexiconPhraseToVocal(phrase);return;}
      const lexDelete=e.target.closest('[data-eno-lex-delete-study]');if(lexDelete){const study=lexiconStudies.find(item=>item.id===lexDelete.dataset.enoLexDeleteStudy);if(study&&window.confirm(`Delete saved sound study “${study.title}”?`)){lexiconStudies=lexiconStudies.filter(item=>item.id!==study.id);safeSet(LEXICON_BOOK,JSON.stringify(lexiconStudies));renderLexiconStudies(lexDelete.closest('[data-eno-window]'));}return;}
      const lexOpen=e.target.closest('[data-eno-lex-open-study]');if(lexOpen){const study=lexiconStudies.find(item=>item.id===lexOpen.dataset.enoLexOpenStudy),win=lexOpen.closest('[data-eno-window]');if(study&&win){lastLexiconStudy=study;const meter=win.querySelector('[data-eno-lex-meter-text]'),sounds=win.querySelector('[data-eno-lex-sounds-text]');if(meter)meter.value=study.phrase;if(sounds)sounds.value=study.phrase;win.querySelectorAll('[data-eno-lex-tab]').forEach(button=>button.setAttribute('aria-selected',String(button.dataset.enoLexTab==='meter')));win.querySelectorAll('[data-eno-lex-panel]').forEach(panel=>panel.hidden=panel.dataset.enoLexPanel!=='meter');if(study.search){const field=win.querySelector('[data-eno-lex-phonemes]');if(field)field.value=study.search.query;win.querySelectorAll('[data-eno-lex-tab]').forEach(button=>button.setAttribute('aria-selected',String(button.dataset.enoLexTab==='phoneme')));win.querySelectorAll('[data-eno-lex-panel]').forEach(panel=>panel.hidden=panel.dataset.enoLexPanel!=='phoneme');handleLexiconAction('phonemes',win);}else handleLexiconAction('scan',win);}return;}
      if(!e.target.closest('[data-eno-volume-panel],[data-eno-audio-toggle]')){$e('[data-eno-volume-panel]').hidden=true;$e('[data-eno-audio-toggle]').setAttribute('aria-expanded','false');}
      if(!e.target.closest('[data-eno-clock-panel],[data-eno-clock-toggle]')){$e('[data-eno-clock-panel]').hidden=true;$e('[data-eno-clock-toggle]').setAttribute('aria-expanded','false');}
      const launch=e.target.closest('[data-eno-launch]');if(launch){$e('[data-eno-clock-panel]').hidden=true;$e('[data-eno-clock-toggle]').setAttribute('aria-expanded','false');$e('[data-eno-volume-panel]').hidden=true;$e('[data-eno-audio-toggle]').setAttribute('aria-expanded','false');openApp(launch.dataset.enoLaunch);return;}
      if(e.target.closest('[data-eno-main-task]')){restoreMainStudio();return;}
