      if(e.target.closest('[data-eno-clock-toggle]')){const panel=$e('[data-eno-clock-panel]');panel.hidden=!panel.hidden;e.target.closest('[data-eno-clock-toggle]').setAttribute('aria-expanded',String(!panel.hidden));return;}
