    const umbraFullscreen=bindOsFullscreen(root,q('[data-u-action="fullscreen"]'),message=>note(message));
    const getCtx=layer=>layer?.canvas?.getContext('2d',{willReadFrequently:true});
    const escU=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const safeName=s=>String(s||'Untitled').replace(/[\\/:*?"<>|]/g,'-').slice(0,80)||'Untitled';
    const appTitles={layers:'Layer Studio',filters:'Filter Lab',color:'Color Lab',assets:'Asset Vault',forge:'Pixel Forge',text:'Text Studio',export:'Export Center',history:'History',new:'New Document'};
    const updateTitle=()=>{if(disposed)return;q('[data-u-doc-title]').textContent=`${doc.name} - UMBRA Editor`;q('[data-u-document-size]').textContent=`${doc.width} × ${doc.height}`;q('[data-u-layer-count]').textContent=String(layers.length).padStart(2,'0');q('[data-u-doc-state]').textContent=dirty?'UNSAVED CHANGES':'SAVED LOCALLY';};
