    function setDocumentSize(w,h){doc.width=clamp(Math.round(Number(w)||1200),64,MAX_DIM);doc.height=clamp(Math.round(Number(h)||760),64,MAX_DIM);canvas.width=preview.width=doc.width;canvas.height=preview.height=doc.height;layers.forEach(l=>{if(l.canvas.width!==doc.width||l.canvas.height!==doc.height){const old=l.canvas,n=makeCanvas();n.getContext('2d').drawImage(old,0,0,Math.min(old.width,doc.width),Math.min(old.height,doc.height));l.canvas=n;if(l.mask){const oldm=l.mask,m=makeCanvas();m.getContext('2d').drawImage(oldm,0,0,Math.min(oldm.width,doc.width),Math.min(oldm.height,doc.height));l.mask=m;}}});fitZoom();updateTitle();scheduleRender();}
