    function setZoom(value){fitMode=false;zoom=clamp(value,.08,2.5);stack.style.width=Math.round(doc.width*zoom)+'px';stack.style.height=Math.round(doc.height*zoom)+'px';canvas.style.width=preview.style.width=Math.round(doc.width*zoom)+'px';canvas.style.height=preview.style.height=Math.round(doc.height*zoom)+'px';q('[data-u-zoom]').textContent=Math.round(zoom*100)+'%';}
