    function setTool(next){tool=next;$$u('[data-u-tool]').forEach(b=>b.classList.toggle('active',b.dataset.uTool===tool));q('[data-u-tool-name]').textContent=tool.toUpperCase();note(tool.toUpperCase()+' tool selected.');}
    function updateLayerList(){const markup=layers.slice().reverse().map(l=>`<div class="umbra-layer-row ${l.id===activeLayerId?'selected':''}" data-u-layer-row="${escU(l.id)}"><button type="button" class="umbra-layer-eye" data-u-layer-visible="${escU(l.id)}" aria-label="Toggle ${escU(l.name)} visibility">${l.visible?'◉':'○'}</button><button type="button" class="umbra-layer-name" data-u-layer-select="${escU(l.id)}"><span>${l.mask?'◩':'▧'}</span><b>${escU(l.name)}</b><small>${l.mask?'MASK':'PIXEL'}</small></button><button type="button" class="umbra-layer-lock" data-u-layer-lock="${escU(l.id)}" title="${l.locked?'Unlock':'Lock'} layer">${l.locked?'▣':'□'}</button></div>`).join('');$$u('[data-u-layer-list],[data-u-layer-list-large]').forEach(el=>el.innerHTML=markup||'<p class="umbra-empty-list">No layers yet.</p>');const l=current();q('[data-u-layer-opacity]').value=Math.round((l?.opacity??1)*100);q('[data-u-layer-opacity-out]').textContent=Math.round((l?.opacity??1)*100)+'%';q('[data-u-layer-blend]').value=l?.blend||'source-over';q('[data-u-layer-count]').textContent=String(layers.length).padStart(2,'0');updateAssetList();}
