    function updateAssetList(){const html=layers.map(l=>`<div class="umbra-asset-row"><span>▧</span><b>${escU(l.name)}</b><button type="button" data-u-layer-select="${escU(l.id)}">SELECT</button></div>`).join('');const el=q('[data-u-asset-list]');if(el)el.innerHTML=html||'<p class="umbra-empty-list">No imported assets yet.</p>';}
