    function tokenList(node){const source=[node.title,node.content,node.tags,node.url,node.fileName,node.type].filter(Boolean).join(' ').toLowerCase();return source.match(/[a-z0-9][a-z0-9_-]{1,}/g)||[];}
    const workerSource=`const stop=new Set('about after again all also an and any are as at be been before between both but by can could did do does for from get got had has have he her here hers him his how i if in into is it its just may me more most my no not of off on once one only or other our out over own same she should so some such than that the their them then there these they this those through to too under up us use very was we were what when where which while who why will with would you your the via using user'.split(' '));function terms(s){const a=(s||'').toLowerCase().match(/[a-z0-9][a-z0-9_-]{1,}/g)||[];const m=new Map();for(const t of a){if(stop.has(t))continue;m.set(t,(m.get(t)||0)+1)}return m}onmessage=e=>{const nodes=e.data.nodes||[],docs=nodes.map(n=>terms([n.title,n.content,n.tags,n.url,n.fileName,n.type].filter(Boolean).join(' '))),df=new Map();for(const d of docs)for(const t of d.keys())df.set(t,(df.get(t)||0)+1);const vectors=docs.map(d=>{const v=new Map();let norm=0;for(const [t,c] of d){const w=(1+Math.log(c))*Math.log(1+nodes.length/(1+(df.get(t)||1)));v.set(t,w);norm+=w*w}return{v,norm:Math.sqrt(norm)}}),scores=[];for(let i=0;i<nodes.length;i++){const best=[];for(let j=i+1;j<nodes.length;j++){const a=vectors[i],b=vectors[j];if(!a.norm||!b.norm)continue;let dot=0,shared=0;for(const [t,w] of a.v){const v=b.v.get(t);if(v){dot+=w*v;shared++}}const score=dot/(a.norm*b.norm);if(score>.105&&shared>=1)best.push({a:nodes[i].id,b:nodes[j].id,score,shared,terms:[...a.v.keys()].filter(t=>b.v.has(t)).slice(0,4)})}best.sort((x,y)=>y.score-x.score);scores.push(...best.slice(0,4));}const seen=new Set();postMessage(scores.filter(x=>{const k=x.a+'|'+x.b;if(seen.has(k))return false;seen.add(k);return true}))};`;
    function initGravity(){try{const blob=new Blob([workerSource],{type:'text/javascript'});gravityBlobUrl=URL.createObjectURL(blob);gravityWorker=new Worker(gravityBlobUrl);gravityWorker.onmessage=e=>{if(destroyed)return;autoEdges=e.data||[];renderEdges();updateStats();};gravityWorker.onerror=()=>{if(destroyed)return;gravityWorker?.terminate();gravityWorker=null;recomputeGravityFallback();};}catch(_){gravityWorker=null;}}
