    function fitMesh(){if(!workspace.nodes.length){zoom=1;const r=stage.getBoundingClientRect();tx=r.width/2-WORLD_W/2;ty=r.height/2-WORLD_H/2;applyView();return;}const xs=workspace.nodes.map(n=>n.x),ys=workspace.nodes.map(n=>n.y),minX=Math.min(...xs),maxX=Math.max(...xs)+236,minY=Math.min(...ys),maxY=Math.max(...ys)+146,r=stage.getBoundingClientRect(),sx=(r.width-130)/(maxX-minX),sy=(r.height-130)/(maxY-minY);zoom=clampA(Math.min(sx,sy,1.15),.32,1.15);tx=(r.width-(minX+maxX)*zoom)/2;ty=(r.height-(minY+maxY)*zoom)/2;applyView();}
    function renderEdges(){const byId=new Map(workspace.nodes.map(n=>[n.id,n])),manual=workspace.edges||[],parts=[];for(const e of [...(gravity?autoEdges:[]),...manual.map(e=>({...e,manual:true,score:1}))]){const a=byId.get(e.a),b=byId.get(e.b);if(!a||!b||a.id===b.id)continue;const ax=a.x+118,ay=a.y+76,bx=b.x+118,by=b.y+76,dx=bx-ax,dy=by-ay,cx=(ax+bx)/2-dy*.12,cy=(ay+by)/2+dx*.12;parts.push(`<path class="${e.manual?'manual':'gravity'}" d="M ${ax} ${ay} Q ${cx} ${cy} ${bx} ${by}" style="--edge-opacity:${Math.min(.82,.18+(e.score||.4)*.65)}"/>`);}edgeSvg.innerHTML=parts.join('');}
