    function renderNodes(){nodeLayer.innerHTML='';const frag=document.createDocumentFragment();for(const n of workspace.nodes){const el=document.createElement('article');el.className=`aether-node aether-node-${n.type}${n.id===selectedId?' selected':''}`;el.dataset.nodeId=n.id;el.style.transform=`translate3d(${n.x}px,${n.y}px,0)`;const preview=(n.content||n.url||n.fileName||'No context added yet.').replace(/\s+/g,' ').slice(0,126);el.innerHTML=`<div class="aether-node-head"><span>${nodeIcon(n.type)}</span><small>${esc(n.type.toUpperCase())}</small><button type="button" data-a-node-menu="${esc(n.id)}" aria-label="Node actions">···</button></div><button class="aether-node-title" type="button" data-a-node-select="${esc(n.id)}">${esc(n.title||'Untitled')}</button><p>${esc(preview)}</p><div class="aether-node-foot"><span>${esc((n.tags||[]).slice(0,2).join(' · ')||n.fileName||'CONTEXT')}</span><b>${n.type==='file'?`${(n.size/1048576).toFixed(n.size>1048576?1:2)} MB`:'↗'}</b></div>`;if((n.type==='link'||n.type==='api')&&n.url){const link=document.createElement('a');link.className='aether-node-open';link.href=n.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='OPEN ↗';el.append(link);}frag.append(el);}nodeLayer.append(frag);q('[data-a-empty]').hidden=workspace.nodes.length>0;renderEdges();updateStats();applySearch();}
