    function addNode(data,position=null){if(workspace.nodes.length>=MAX_NODES){say(`Workspace limit: ${MAX_NODES} nodes.`);return null;}const base=centerPoint(),count=workspace.nodes.length,angle=count*2.399963,ring=150+Math.sqrt(count)*60,p=position||{x:clampA(base.x+Math.cos(angle)*ring,80,WORLD_W-280),y:clampA(base.y+Math.sin(angle)*ring,80,WORLD_H-220)};const n={id:uidA(),type:data.type||'note',title:cleanText(data.title||'Untitled'),content:cleanText(data.content||''),url:data.url||'',tags:Array.isArray(data.tags)?data.tags.slice(0,12):String(data.tags||'').split(',').map(s=>s.trim()).filter(Boolean).slice(0,12),x:clampA(p.x,20,WORLD_W-260),y:clampA(p.y,20,WORLD_H-190),fileName:data.fileName||'',size:Number(data.size)||0,mime:data.mime||'',asset:data.asset||null,created:Date.now()};workspace.nodes.push(n);selectedId=n.id;renderNodes();selectNode(n.id);queueGravity();queueSave();return n;}
