    async function exportReality(){const pack=portableState();let total=0,skipped=[];for(const n of pack.workspace.nodes){if(n.type!=='file'||!n.asset)continue;const file=await getAsset(n.asset).catch(()=>null);if(!file){skipped.push(n.fileName);continue;}if(total+file.size>8*1024*1024){skipped.push(n.fileName);continue;}const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]||'');r.onerror=()=>reject(r.error);r.readAsDataURL(file);});n.asset={...n.asset,embedded:true,data};total+=file.size;}const blob=new Blob([JSON.stringify(pack)],{type:'application/json'});downloadBlob(blob,`${(workspace.name||'aether-reality').replace(/[^a-z0-9_-]+/gi,'-').toLowerCase()}.aether`);say(skipped.length?`Reality exported. ${skipped.length} large attachment(s) remain local.`:'Portable reality exported with attachments.');}
