    function createShareUrl(){const payload={format:'Aether.OS Reality',version:1,workspace:{name:workspace.name,nodes:workspace.nodes.map(n=>({id:n.id,type:n.type,title:n.title,content:n.content,url:n.url,tags:n.tags,fileName:n.fileName,size:n.size,mime:n.mime,x:n.x,y:n.y})),edges:workspace.edges||[]}};const encoded=encodeBase64Url(JSON.stringify(payload));return `${location.href.split('#')[0]}#aether=${encoded}`;}
    async function copyText(text){try{await navigator.clipboard.writeText(text);return true;}catch(_){const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();return ok;}}
