    function importSharedHash(){const m=location.hash.match(/(?:^#|&)aether=([^&]+)/);if(!m)return false;try{const pack=JSON.parse(decodeBase64Url(m[1]));if(pack.format!=='Aether.OS Reality'||!Array.isArray(pack.workspace?.nodes))return false;const imported=[],idMap=new Map();for(const raw of pack.workspace.nodes.slice(0,MAX_NODES)){const n=sanitizeImportedNode(raw);n.asset=null;if(raw.type==='file')n.content=`${n.content||''}\n[Local attachment is not included in this share URL.]`;idMap.set(raw.id,n.id);imported.push(n);}workspace=makeWorkspace(pack.workspace.name||'Shared reality');workspace.nodes=imported;workspace.edges=(pack.workspace.edges||[]).slice(0,2000).map(e=>({a:idMap.get(e.a),b:idMap.get(e.b)})).filter(e=>e.a&&e.b&&e.a!==e.b);workspaces.push(workspace);currentId=workspace.id;refreshWorkspaceSelect();history.replaceState(null,'',location.pathname+location.search);return true;}catch(error){console.warn('Aether shared state could not be read:',error);return false;}}
    function updateViewFromSaved(){const v=workspace.view||{};if(Number.isFinite(v.scale)){zoom=clampA(v.scale,.25,2.5);tx=Number(v.x)||0;ty=Number(v.y)||0;}else{zoom=1;const r=stage.getBoundingClientRect();tx=r.width/2-WORLD_W/2;ty=r.height/2-WORLD_H/2;}applyView();}
    function addManualEdge(a,b){if(!a||!b||a===b)return;const exists=(workspace.edges||[]).some(e=>(e.a===a&&e.b===b)||(e.a===b&&e.b===a));if(exists){say('These nodes are already connected.');return;}workspace.edges.push({a,b,created:Date.now()});renderEdges();updateStats();queueSave();say('Pinned a manual context thread.');}
    function startConnect(id){connectSource=id;root.classList.add('aether-connecting');q('[data-a-connect-hint]').hidden=false;say('Choose another node to pin a relationship.');}
    function setInspector(open){inspector.classList.toggle('is-open',open);root.classList.toggle('aether-inspector-open',open);}
    function openNode(id){const n=workspace.nodes.find(x=>x.id===id);if(!n)return;if(n.type==='link'||n.type==='api'){if(!n.url){say('This node does not contain a valid web address.');return;}window.open(n.url,'_blank','noopener,noreferrer');return;}if(n.type==='file'){getAsset(n.asset).then(blob=>{if(!blob){say('The original local file is unavailable.');return;}downloadBlob(blob,n.fileName||n.title);}).catch(()=>say('Could not open this local attachment.'));return;}const ok=copyText(n.content||n.title);ok.then?ok.then(v=>say(v?'Copied node context.':'Clipboard unavailable.')):say(ok?'Copied node context.':'Clipboard unavailable.');}
    async function deleteNode(id){const n=workspace.nodes.find(x=>x.id===id);if(!n)return;if(!window.confirm(`Delete “${n.title||'Untitled'}” from this workspace? Its attachment and connected links will also be removed.`))return;workspace.nodes=workspace.nodes.filter(x=>x.id!==id);workspace.edges=(workspace.edges||[]).filter(e=>e.a!==id&&e.b!==id);if(selectedId===id)selectedId=null;renderNodes();selectNode(null);queueGravity();queueSave();let attachmentWarning='';if(n.asset){try{await removeAsset(n.asset);}catch(_){attachmentWarning=' The node is gone, but its stored attachment could not be cleaned up.';}}say(`Deleted ${n.title||'node'}.${attachmentWarning}`);}
    function importNodeForm(event){event.preventDefault();const type=q('[data-a-new-type]').value,title=q('[data-a-new-title]').value.trim(),url=q('[data-a-new-url]').value.trim(),content=q('[data-a-new-content]').value,tags=q('[data-a-new-tags]').value;if(!title){say('Give this node a title first.');return;}let safeUrl='';if(['link','api'].includes(type)){try{const parsed=new URL(url);if(!['http:','https:'].includes(parsed.protocol))throw new Error();safeUrl=parsed.href;}catch(_){say('Enter a valid http or https URL.');return;}}const n=addNode({type,title,url:safeUrl,content,tags});q('[data-a-node-dialog]').close();if(n)say('Added to the contextual mesh.');}
    function renderWorkspaceList(){refreshWorkspaceSelect();}
    async function createWorkspace(){await persistWorkspace().catch(()=>{});workspace=makeWorkspace(`Project ${workspaces.length+1}`);workspaces.push(workspace);currentId=workspace.id;refreshWorkspaceSelect();selectedId=null;connectSource=null;autoEdges=[];renderNodes();fitMesh();queueSave();selectNode(null);say('New project workspace created.');}
    async function deleteWorkspace(){if(workspaces.length<=1){say('Keep at least one workspace. This last project cannot be deleted.');return;}const target=workspace;if(!window.confirm(`Delete project “${target.name}” and its ${(target.nodes||[]).length} node(s) and attachments? This cannot be undone.`))return;clearTimeout(saveTimer);await persistWorkspace().catch(()=>{});let attachmentFailures=0;for(const node of target.nodes||[])if(node.asset){try{await removeAsset(node.asset);}catch(_){attachmentFailures++;}}workspaces=workspaces.filter(item=>item.id!==target.id);await idbDelete('workspaces',target.id).catch(()=>{});try{localStorage.setItem(WORKSPACE_KEY,JSON.stringify(workspaces));}catch(_){}workspace=safeJsonClone(workspaces.slice().sort((a,b)=>(b.updated||0)-(a.updated||0))[0]);currentId=workspace.id;selectedId=null;connectSource=null;autoEdges=[];refreshWorkspaceSelect();renderNodes();updateViewFromSaved();queueGravity();selectNode(null);await persistWorkspace();say(`Deleted project ${target.name}. Opened ${workspace.name}.${attachmentFailures?` ${attachmentFailures} attachment(s) could not be removed from local storage.`:''}`);}
    async function switchWorkspace(id){if(!id||id===currentId)return;await persistWorkspace().catch(()=>{});let item=workspaces.find(w=>w.id===id);if(!item){try{item=await idbGet('workspaces',id);}catch(_){}}if(!item)return;workspace=safeJsonClone(item);currentId=workspace.id;selectedId=null;connectSource=null;autoEdges=[];renderWorkspaceList();renderNodes();updateViewFromSaved();queueGravity();selectNode(null);say(`Opened ${workspace.name}.`);}
    function bindNodeActions(event){const remove=event.target.closest('[data-a-node-menu]');if(remove){event.stopPropagation();const id=remove.dataset.aNodeMenu;selectNode(id);setInspector(true);return;}const action=event.target.closest('[data-a-node-select]');if(action){event.stopPropagation();const id=action.dataset.aNodeSelect;if(connectSource){addManualEdge(connectSource,id);connectSource=null;root.classList.remove('aether-connecting');q('[data-a-connect-hint]').hidden=true;q('[data-a-connect-mode]').setAttribute('aria-pressed','false');return;}selectNode(id);setInspector(true);return;}const rel=event.target.closest('[data-a-related-node]');if(rel){selectNode(rel.dataset.aRelatedNode);setInspector(true);const n=workspace.nodes.find(x=>x.id===rel.dataset.aRelatedNode);if(n){tx=stage.clientWidth/2-(n.x+118)*zoom;ty=stage.clientHeight/2-(n.y+70)*zoom;applyView();}return;}const open=event.target.closest('.aether-node-open');if(open){event.stopPropagation();return;}}
    function nodePointerDown(event){const node=event.target.closest('.aether-node');if(!node||event.button!==0||event.target.closest('button,a'))return;const id=node.dataset.nodeId;if(connectSource){addManualEdge(connectSource,id);connectSource=null;root.classList.remove('aether-connecting');q('[data-a-connect-hint]').hidden=true;q('[data-a-connect-mode]').setAttribute('aria-pressed','false');return;}selectNode(id);setInspector(true);nodeDrag={id,x:event.clientX,y:event.clientY,ox:workspace.nodes.find(n=>n.id===id).x,oy:workspace.nodes.find(n=>n.id===id).y,pointer:event.pointerId};try{node.setPointerCapture(event.pointerId);}catch(_){}event.preventDefault();}
    function pointerMove(event){if(nodeDrag){const n=workspace.nodes.find(x=>x.id===nodeDrag.id);if(!n)return;n.x=clampA(nodeDrag.ox+(event.clientX-nodeDrag.x)/zoom,0,WORLD_W-250);n.y=clampA(nodeDrag.oy+(event.clientY-nodeDrag.y)/zoom,0,WORLD_H-180);const el=nodeLayer.querySelector(`[data-node-id="${CSS.escape(n.id)}"]`);if(el)el.style.transform=`translate3d(${n.x}px,${n.y}px,0)`;renderEdges();return;}if(pan){tx=pan.tx+event.clientX-pan.x;ty=pan.ty+event.clientY-pan.y;applyView();}}
    function pointerUp(){if(nodeDrag){nodeDrag=null;queueSave();}pan=null;}
    function stageDown(event){if(event.target.closest('.aether-node'))return;const canPan=event.button===1||event.button===2||panMode||event.shiftKey||keys.space;if(!canPan)return;pan={x:event.clientX,y:event.clientY,tx,ty};try{stage.setPointerCapture(event.pointerId);}catch(_){}event.preventDefault();}
    const keys={space:false};
    function zoomAt(clientX,clientY,factor){const r=stage.getBoundingClientRect(),px=clientX-r.left,py=clientY-r.top,old=zoom;zoom=clampA(zoom*factor,.25,2.5);tx=px-(px-tx)*(zoom/old);ty=py-(py-ty)*(zoom/old);applyView();queueSave();}
    function onWheel(event){event.preventDefault();const factor=Math.exp(-event.deltaY*.0015);zoomAt(event.clientX,event.clientY,factor);}
    function fitSelection(){if(selectedId){const n=workspace.nodes.find(x=>x.id===selectedId);if(n){zoom=Math.max(zoom,.8);tx=stage.clientWidth/2-(n.x+118)*zoom;ty=stage.clientHeight/2-(n.y+70)*zoom;applyView();return;}}fitMesh();queueSave();}
    function workerMessage(event){if(!event.data)return;const msg=event.data;if(msg.kind==='aether-chunk'){const pack=peerChunks.get(msg.id)||{total:msg.total,parts:[]};pack.parts[msg.index]=msg.data;peerChunks.set(msg.id,pack);if(pack.parts.filter(Boolean).length===pack.total){peerChunks.delete(msg.id);const state=JSON.parse(decodeBase64Url(pack.parts.join('')));if(state.format==='Aether.OS Reality')importSharedState(state).catch(()=>say('Incoming reality could not be imported.'));}}}
    async function importSharedState(pack){if(!pack.workspace||!Array.isArray(pack.workspace.nodes))throw new Error('Invalid shared workspace.');const n=makeWorkspace(pack.workspace.name||'Peer reality'),idMap=new Map();n.nodes=pack.workspace.nodes.slice(0,MAX_NODES).map(raw=>{const node=sanitizeImportedNode(raw);node.asset=null;idMap.set(raw.id,node.id);return node;});n.edges=(pack.workspace.edges||[]).slice(0,2000).map(e=>({a:idMap.get(e.a),b:idMap.get(e.b)})).filter(e=>e.a&&e.b&&e.a!==e.b);workspaces.push(n);workspace=n;currentId=n.id;refreshWorkspaceSelect();renderNodes();fitMesh();queueGravity();await persistWorkspace();say('Received a new shared reality.');}
    function closePeer(){try{dataChannel?.close();peer?.close();}catch(_){}dataChannel=null;peer=null;q('[data-a-peer-send]').disabled=true;}
    function handlePeerOpen(){q('[data-a-peer-status]').textContent='CONNECTED / ENCRYPTED DATA CHANNEL OPEN';q('[data-a-peer-send]').disabled=false;}
    function attachChannel(channel){dataChannel=channel;channel.binaryType='arraybuffer';channel.onopen=handlePeerOpen;channel.onclose=()=>{q('[data-a-peer-status]').textContent='PEER DISCONNECTED';q('[data-a-peer-send]').disabled=true;};channel.onerror=()=>q('[data-a-peer-status]').textContent='PEER CHANNEL ERROR';channel.onmessage=e=>{try{const msg=JSON.parse(e.data);if(msg.kind==='aether-chunk')workerMessage({data:msg});}catch(_){}};if(channel.readyState==='open')handlePeerOpen();}
    function rtcConfig(){return q('[data-a-use-stun]').checked?{iceServers:[{urls:'stun:stun.l.google.com:19302'}]}:{iceServers:[]};}
    async function waitIce(pc){if(pc.iceGatheringState==='complete')return;await new Promise(resolve=>{let done=false;const finish=()=>{if(done)return;done=true;clearTimeout(timer);pc.removeEventListener('icegatheringstatechange',check);resolve();},check=()=>{if(pc.iceGatheringState==='complete')finish();},timer=setTimeout(finish,9000);pc.addEventListener('icegatheringstatechange',check);});}
    async function createPeerOffer(){closePeer();peer=new RTCPeerConnection(rtcConfig());attachChannel(peer.createDataChannel('aether-reality',{ordered:true}));const offer=await peer.createOffer();await peer.setLocalDescription(offer);q('[data-a-peer-status]').textContent='GATHERING DIRECT ROUTES…';await waitIce(peer);q('[data-a-peer-text]').value=JSON.stringify({type:'offer',sdp:peer.localDescription.sdp});q('[data-a-peer-status]').textContent='INVITE READY / SEND THIS TEXT TO YOUR PEER';}
    async function applyPeerText(){const input=q('[data-a-peer-text]').value.trim();if(!input)throw new Error('Paste an invite or answer first.');const data=JSON.parse(input);if(data.type==='offer'){closePeer();peer=new RTCPeerConnection(rtcConfig());peer.ondatachannel=e=>attachChannel(e.channel);await peer.setRemoteDescription({type:'offer',sdp:data.sdp});const answer=await peer.createAnswer();await peer.setLocalDescription(answer);q('[data-a-peer-status]').textContent='GATHERING DIRECT ROUTES…';await waitIce(peer);q('[data-a-peer-text]').value=JSON.stringify({type:'answer',sdp:peer.localDescription.sdp});q('[data-a-peer-status]').textContent='ANSWER READY / SEND IT BACK TO THE HOST';}else if(data.type==='answer'&&peer){await peer.setRemoteDescription({type:'answer',sdp:data.sdp});q('[data-a-peer-status]').textContent='ANSWER APPLIED / CONNECTING…';}else throw new Error('This is not a supported invite or no host session exists.');}
    async function sendPeerWorkspace(){if(!dataChannel||dataChannel.readyState!=='open')throw new Error('The peer channel is not connected.');const raw=JSON.stringify(portableState()),encoded=encodeBase64Url(raw);if(encoded.length>1500000)throw new Error('Workspace state exceeds the peer transfer size limit. Export a .aether file instead.');const size=12000,total=Math.ceil(encoded.length/size),id=uidA();for(let i=0;i<total;i++){const payload=JSON.stringify({kind:'aether-chunk',id,index:i,total,data:encoded.slice(i*size,(i+1)*size)});while(dataChannel.bufferedAmount>256000)await new Promise(resolve=>{dataChannel.onbufferedamountlow=resolve;dataChannel.bufferedAmountLowThreshold=128000;});dataChannel.send(payload);}q('[data-a-peer-status]').textContent=`SENT ${workspace.nodes.length} NODES / LOCAL ATTACHMENTS NOT INCLUDED`;}
    function setDialogOpen(d,open){if(open)d.showModal();else d.close();}
    function addEvent(target,type,fn,opts){target.addEventListener(type,fn,opts);return()=>target.removeEventListener(type,fn,opts);}
    const cleanup=[];
