      if(t.matches('[data-a-sound-lens]')){const dialog=q('[data-a-sound-dialog]');if(!window.CurioidLexicon&&!CurioidKernel.getCapability('echonoise.lexicon.analyze')){say('Open Echonoise OS once to activate its local Lexicon service, then return to Sound Lens.');}dialog.showModal();return;}
