    function drawCube(canvas){if(!canvas)return;const c=canvas.getContext('2d');if(!c)return;const w=canvas.width,h=canvas.height;c.clearRect(0,0,w,h);c.fillStyle='#151719';c.fillRect(0,0,w,h);c.strokeStyle='rgba(255,255,255,.055)';c.lineWidth=1;for(let x=24;x<w;x+=32){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();}for(let y=24;y<h;y+=32){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke();}const sx=Math.sin(cubeAngles.x),cx=Math.cos(cubeAngles.x),sy=Math.sin(cubeAngles.y),cy=Math.cos(cubeAngles.y);const pts=[];for(let z of [-1,1])for(let y of [-1,1])for(let x of [-1,1]){const rx=x*cy-z*sy,rz=x*sy+z*cy,ry=y*cx-rz*sx,rz2=y*sx+rz*cx,scale=175/(3.6-rz2*.36);pts.push([w/2+rx*scale,h/2+ry*scale]);}const order=[[0,1],[0,2],[0,4],[1,3],[1,5],[2,3],[2,6],[3,7],[4,5],[4,6],[5,7],[6,7]];c.lineWidth=3;c.strokeStyle='#aeb2b2';order.forEach(([a,b])=>{c.beginPath();c.moveTo(...pts[a]);c.lineTo(...pts[b]);c.stroke();});const faces=[[0,1,3,2],[4,5,7,6],[0,1,5,4],[2,3,7,6],[0,2,6,4],[1,3,7,5]];faces.forEach((face,i)=>{c.beginPath();face.forEach((p,j)=>j?c.lineTo(...pts[p]):c.moveTo(...pts[p]));c.closePath();c.fillStyle=['rgba(220,220,220,.16)','rgba(180,180,180,.13)','rgba(245,245,245,.12)','rgba(130,130,130,.16)','rgba(205,205,205,.1)','rgba(160,160,160,.18)'][i];c.fill();c.strokeStyle='#c3c6c5';c.stroke();});c.fillStyle='#9da2a1';c.font='13px monospace';c.fillText('UNIT VOLUME / 1.000 M³',20,h-20);}
