            <g fill="${palette.accent}" opacity=".75"><circle cx="${n(cx-w*.7)}" cy="${n(cy+h*.45)}" r="3.5"/><circle cx="${n(cx+w*.69)}" cy="${n(cy+h*.43)}" r="3.5"/></g>
