        const savedMood = legacyMoods[item.mood] || item.mood || "random";
        current = { seed: item.seed, mood: savedMood, anatomy: item.anatomy || "random", eyeStyle: item.eyeStyle || "random", mouthStyle: item.mouthStyle || "random", weirdness: Number(item.weirdness ?? 100), structure: item.structure || "mixed", number: item.number || 1 };
